operations.profile_guard:
CREATE OR REPLACE FUNCTION public.profiles_guard_protected_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if pg_catalog.pg_trigger_depth() <= 1 and current_user <> 'service_role' then
    new.is_admin := old.is_admin;
  end if;
  return new;
end;
$function$
